package com.sobrenaturaldirector.composition.model;

import java.util.*;
import com.sobrenaturaldirector.domain.StableId;
import com.sobrenaturaldirector.content.query.ResolutionResult;

public final class ContentRoleBinding {private final String role,requirementId;private final BindingStatus status;private final List<String> candidates;private final String reason;public ContentRoleBinding(String role,String requirementId,BindingStatus status,Collection<String> candidates,String reason){this.role=StableId.require(role,"role");this.requirementId=StableId.require(requirementId,"requirementId");this.status=status==null?BindingStatus.UNRESOLVED:status;this.candidates=Collections.unmodifiableList(new ArrayList<String>(candidates==null?Collections.<String>emptyList():new TreeSet<String>(candidates)));this.reason=reason==null?"":reason;}public static ContentRoleBinding from(String role,String req,ResolutionResult r){if(r==null)return new ContentRoleBinding(role,req,BindingStatus.UNRESOLVED,null,"no resolution result");BindingStatus s;if(r.getStatus()==ResolutionResult.Status.RESOLVED)s=BindingStatus.RESOLVED;else if(r.getStatus()==ResolutionResult.Status.ADAPTER_REQUIRED)s=BindingStatus.ADAPTER_REQUIRED;else if(r.getStatus()==ResolutionResult.Status.INSUFFICIENT_EVIDENCE||r.getStatus()==ResolutionResult.Status.UNKNOWN)s=BindingStatus.UNSAFE;else s=BindingStatus.DEFERRED;List<String> ids=new ArrayList<String>();for(ResolutionResult.Candidate c:r.getCandidates())if(c.getEntry()!=null)ids.add(c.getEntry().getKey().getValue());return new ContentRoleBinding(role,req,s,ids,r.getReason());}public String getRole(){return role;}public String getRequirementId(){return requirementId;}public BindingStatus getStatus(){return status;}public List<String> getCandidates(){return candidates;}public String getReason(){return reason;}}
